+// limitations under the License.
+
+package mangos
+
+import (
+	"encoding/binary"
+	"io"
+	"net"
+	"sync"
+)
+
+// conn implements the Pipe interface on top of net.Conn.  The
+// assumption is that transports using this have similar wire protocols,
+// and conn is meant to be used as a building block.
+type conn struct {
+	c     net.Conn
+	proto Protocol
+	sock  Socket
+	open  bool
+	props map[string]interface{}
+	maxrx int64
+	sync.Mutex
+}
+
+// connipc is *almost* like a regular conn, but the IPC protocol insists
+// on stuffing a leading byte (valued 1) in front of messages.  This is for
+// compatibility with nanomsg -- the value cannot ever be anything but 1.
+type connipc struct {
+	conn
+}
+
+// Recv implements the Pipe Recv method.  The message received is expected as
+// a 64-bit size (network byte order) followed by the message itself.
+func (p *conn) Recv() (*Message, error) {
+
+	var sz int64
+	var err error
+	var msg *Message
+
+	if err = binary.Read(p.c, binary.BigEndian, &sz); err != nil {
+		return nil, err
+	}
+
+	// Limit messages to the maximum receive value, if not
+	// unlimited.  This avoids a potential denaial of service.
+	if sz < 0 || (p.maxrx > 0 && sz > p.maxrx) {
+		return nil, ErrTooLong
+	}
+	msg = NewMessage(int(sz))
+	msg.Body = msg.Body[0:sz]
+	if _, err = io.ReadFull(p.c, msg.Body); err != nil {
+		msg.Free()
+		return nil, err
+	}
+	return msg, nil
+}
+
+// Send implements the Pipe Send method.  The message is sent as a 64-bit
+// size (network byte order) followed by the message itself.
+func (p *conn) Send(msg *Message) error {
+
+	l := uint64(len(msg.Header) + len(msg.Body))
+
+	if msg.Expired() {
+		msg.Free()
+		return nil
+	}
+
+	// send length header
+	if err := binary.Write(p.c, binary.BigEndian, l); err != nil {
+		return err
+	}
+	if _, err := p.c.Write(msg.Header); err != nil {
+		return err
+	}
+	// hope this works
+	if _, err := p.c.Write(msg.Body); err != nil {
+		return err
+	}
+	msg.Free()
+	return nil
+}
+
+// LocalProtocol returns our local protocol number.
+func (p *conn) LocalProtocol() uint16 {
+	return p.proto.Number()
+}
+
+// RemoteProtocol returns our peer's protocol number.
+func (p *conn) RemoteProtocol() uint16 {
+	return p.proto.PeerNumber()
+}
+
+// Close implements the Pipe Close method.
+func (p *conn) Close() error {
+	p.Lock()
+	defer p.Unlock()
+	if p.IsOpen() {
+		p.open = false
+		return p.c.Close()
+	}
+	return nil
+}
+
+// IsOpen implements the PipeIsOpen method.
+func (p *conn) IsOpen() bool {
+	return p.open
+}
+
+func (p *conn) GetProp(n string) (interface{}, error) {
+	if v, ok := p.props[n]; ok {
+		return v, nil
+	}
+	return nil, ErrBadProperty
+}
+
+// NewConnPipe allocates a new Pipe using the supplied net.Conn, and
+// initializes it.  It performs the handshake required at the SP layer,
+// only returning the Pipe once the SP layer negotiation is complete.
+//
+// Stream oriented transports can utilize this to implement a Transport.
+// The implementation will also need to implement PipeDialer, PipeAccepter,
+// and the Transport enclosing structure.   Using this layered interface,
+// the implementation needn't bother concerning itself with passing actual
+// SP messages once the lower layer connection is established.
+func NewConnPipe(c net.Conn, sock Socket, props ...interface{}) (Pipe, error) {
+	p := &conn{c: c, proto: sock.GetProtocol(), sock: sock}
+
+	if err := p.handshake(props); err != nil {
+		return nil, err
+	}
+
+	return p, nil
+}
+
+// connHeader is exchanged during the initial handshake.
+type connHeader struct {
+	Zero    byte // must be zero
+	S       byte // 'S'
+	P       byte // 'P'
+	Version byte // only zero at present
+	Proto   uint16
+	Rsvd    uint16 // always zero at present
+}
+
+// handshake establishes an SP connection between peers.  Both sides must
+// send the header, then both sides must wait for the peer's header.
+// As a side effect, the peer's protocol number is stored in the conn.
+// Also, various properties are initialized.
+func (p *conn) handshake(props []interface{}) error {
+	var err error
+
+	p.props = make(map[string]interface{})
+	p.props[PropLocalAddr] = p.c.LocalAddr()
+	p.props[PropRemoteAddr] = p.c.RemoteAddr()
+
+	for len(props) >= 2 {
+		switch name := props[0].(type) {
+		case string:
+			p.props[name] = props[1]
+		default:
+			return ErrBadProperty
+		}
+		props = props[2:]
+	}
+
+	if v, e := p.sock.GetOption(OptionMaxRecvSize); e == nil {
+		// socket guarantees this is an integer
+		p.maxrx = int64(v.(int))
+	}
+
+	h := connHeader{S: 'S', P: 'P', Proto: p.proto.Number()}
+	if err = binary.Write(p.c, binary.BigEndian, &h); err != nil {
+		return err
+	}
+	if err = binary.Read(p.c, binary.BigEndian, &h); err != nil {
+		p.c.Close()
+		return err
+	}
+	if h.Zero != 0 || h.S != 'S' || h.P != 'P' || h.Rsvd != 0 {
+		p.c.Close()
+		return ErrBadHeader
+	}
+	// The only version number we support at present is "0", at offset 3.
+	if h.Version != 0 {
+		p.c.Close()
+		return ErrBadVersion
+	}
+
+	// The protocol number lives as 16-bits (big-endian) at offset 4.
+	if h.Proto != p.proto.PeerNumber() {
+		p.c.Close()
+		return ErrBadProto
+	}
+	p.open = true
+	return nil
+}

@@ -0,0 +1,719 @@
+// Copyright 2018 The Mangos Authors
+//
+// Licensed under the Apache License, Version 2.0 (the "License");
+// you may not use file except in compliance with the License.
+// You may obtain a copy of the license at
+//
+//    http://www.apache.org/licenses/LICENSE-2.0
+//
+// Unless required by applicable law or agreed to in writing, software
+// distributed under the License is distributed on an "AS IS" BASIS,
+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+
+package mangos
+
+import (
+	"fmt"
+	"strings"
+	"sync"
+	"time"
+)
+
+// defaultQLen is the default length of the upper read/write queues.
+const defaultQLen = 128
+
+// defaultMaxRxSize is the default maximum Rx size
+const defaultMaxRxSize = 1024 * 1024
+
+// socket is the meaty part of the core information.
+type socket struct {
+	proto Protocol
+
+	sync.Mutex
+
+	uwq      chan *Message // upper write queue
+	uwqLen   int           // upper write queue buffer length
+	urq      chan *Message // upper read queue
+	urqLen   int           // upper read queue buffer length
+	closeq   chan struct{} // closed when user requests close
+	recverrq chan struct{} // signaled when an error is pending
+
+	closing    bool  // true if Socket was closed at API level
+	active     bool  // true if either Dial or Listen has been successfully called
+	bestEffort bool  // true if OptionBestEffort is set
+	recverr    error // error to return on attempts to Recv()
+	senderr    error // error to return on attempts to Send()
+
+	rdeadline  time.Duration
+	wdeadline  time.Duration
+	reconntime time.Duration // reconnect time after error or disconnect
+	reconnmax  time.Duration // max reconnect interval
+	linger     time.Duration
+	maxRxSize  int // max recv size
+
+	pipes map[*pipe]struct{}
+
+	listeners []*listener
+
+	transports map[string]Transport
+
+	// These are conditional "type aliases" for our self
+	sendhook ProtocolSendHook
+	recvhook ProtocolRecvHook
+
+	// Port hook -- called when a port is added or removed
+	porthook PortHook
+}
+
+func (sock *socket) addPipe(tranpipe Pipe, d *dialer, l *listener) *pipe {
+	p := newPipe(tranpipe)
+	p.d = d
+	p.l = l
+
+	// Either listener or dialer is non-nil -- this could be an assert
+	if l == nil && d == nil {
+		p.Close()
+		return nil
+	}
+
+	sock.Lock()
+	if fn := sock.porthook; fn != nil {
+		sock.Unlock()
+		if !fn(PortActionAdd, p) {
+			p.Close()
+			return nil
+		}
+		sock.Lock()
+	}
+	if sock.pipes == nil {
+		sock.Unlock()
+		p.Close()
+		return nil
+	}
+	p.sock = sock
+	sock.pipes[p] = struct{}{}
+	sock.Unlock()
+	sock.proto.AddEndpoint(p)
+	return p
+}
+
+func (sock *socket) remPipe(p *pipe) {
+
+	sock.proto.RemoveEndpoint(p)
+
+	sock.Lock()
+	delete(sock.pipes, p)
+	sock.Unlock()
+}
+
+func newSocket(proto Protocol) *socket {
+	sock := new(socket)
+	sock.uwqLen = defaultQLen
+	sock.urqLen = defaultQLen
+	sock.uwq = make(chan *Message, sock.uwqLen)
+	sock.urq = make(chan *Message, sock.urqLen)
+	sock.closeq = make(chan struct{})
+	sock.recverrq = make(chan struct{})
+	sock.reconntime = time.Millisecond * 100
+	sock.reconnmax = time.Duration(0)
+	sock.proto = proto
+	sock.transports = make(map[string]Transport)
+	sock.linger = time.Second
+	sock.maxRxSize = defaultMaxRxSize
+	sock.pipes = make(map[*pipe]struct{})
+
+	// Add some conditionals now -- saves checks later
+	if i, ok := interface{}(proto).(ProtocolRecvHook); ok {
+		sock.recvhook = i.(ProtocolRecvHook)
+	}
+	if i, ok := interface{}(proto).(ProtocolSendHook); ok {
+		sock.sendhook = i.(ProtocolSendHook)
+	}
+
+	proto.Init(sock)
+
+	return sock
+}
+
+// MakeSocket is intended for use by Protocol implementations.  The intention
+// is that they can wrap this to provide a "proto.NewSocket()" implementation.
+func MakeSocket(proto Protocol) Socket {
+	return newSocket(proto)
+}
+
+// Implementation of ProtocolSocket bits on socket.  This is the middle
+// API presented to Protocol implementations.
+
+func (sock *socket) SendChannel() <-chan *Message {
+	sock.Lock()
+	defer sock.Unlock()
+	return sock.uwq
+}
+
+func (sock *socket) RecvChannel() chan<- *Message {
+	sock.Lock()
+	defer sock.Unlock()
+	return sock.urq
+}
+
+func (sock *socket) CloseChannel() <-chan struct{} {
+	return sock.closeq
+}
+
+func (sock *socket) SetSendError(err error) {
+	sock.Lock()
+	sock.senderr = err
+	sock.Unlock()
+}
+
+func (sock *socket) SetRecvError(err error) {
+	sock.Lock()
+	sock.recverr = err
+	select {
+	case sock.recverrq <- struct{}{}:
+	default:
+	}
+	sock.Unlock()
+}
+
+//
+// Implementation of Socket bits on socket.  This is the upper API
+// presented to applications.
+//
+
+func (sock *socket) Close() error {
+
+	fin := time.Now().Add(sock.linger)
+
+	DrainChannel(sock.uwq, fin)
+
+	sock.Lock()
+	if sock.closing {
+		sock.Unlock()
+		return ErrClosed
+	}
+	sock.closing = true
+	close(sock.closeq)
+
+	for _, l := range sock.listeners {
+		l.l.Close()
+	}
+	pipes := sock.pipes
+	sock.pipes = nil
+	sock.Unlock()
+
+	// A second drain, just to be sure.  (We could have had device or
+	// forwarded messages arrive since the last one.)
+	DrainChannel(sock.uwq, fin)
+
+	// And tell the protocol to shutdown and drain its pipes too.
+	sock.proto.Shutdown(fin)
+
+	for p := range pipes {
+		p.Close()
+	}
+
+	return nil
+}
+
+func (sock *socket) SendMsg(msg *Message) error {
+
+	sock.Lock()
+	e := sock.senderr
+	if e != nil {
+		sock.Unlock()
+		return e
+	}
+	sock.Unlock()
+	if sock.sendhook != nil {
+		if ok := sock.sendhook.SendHook(msg); !ok {
+			// just drop it silently
+			msg.Free()
+			return nil
+		}
+	}
+	sock.Lock()
+	useBestEffort := sock.bestEffort
+	wdeadline := sock.wdeadline
+
+	if wdeadline != 0 {
+		msg.expire = time.Now().Add(wdeadline)
+	} else {
+		msg.expire = time.Time{}
+	}
+	sock.Unlock()
+
+	if !useBestEffort {
+		timeout := mkTimer(wdeadline)
+		select {
+		case <-timeout:
+			return ErrSendTimeout
+		case <-sock.closeq:
+			return ErrClosed
+		case sock.uwq <- msg:
+			return nil
+		}
+	} else {
+		select {
+		case <-sock.closeq:
+			return ErrClosed
+		case sock.uwq <- msg:
+			return nil
+		default:
+			msg.Free()
+			return nil
+		}
+	}
+}
+
+func (sock *socket) Send(b []byte) error {
+	msg := NewMessage(len(b))
+	msg.Body = append(msg.Body, b...)
+	return sock.SendMsg(msg)
+}
+
+// String just emits a very high level debug.  This avoids
+// triggering race conditions from trying to print %v without
+// holding locks on structure members.
+func (sock *socket) String() string {
+	return fmt.Sprintf("SOCKET[%s](%p)", sock.proto.Name(), sock)
+}
+
+func (sock *socket) RecvMsg() (*Message, error) {
+	sock.Lock()
+	timeout := mkTimer(sock.rdeadline)
+	sock.Unlock()
+
+	for {
+		sock.Lock()
+		if e := sock.recverr; e != nil {
+			sock.Unlock()
+			return nil, e
+		}
+		sock.Unlock()
+		select {
+		case <-timeout:
+			return nil, ErrRecvTimeout
+		case msg := <-sock.urq:
+			if sock.recvhook != nil {
+				if ok := sock.recvhook.RecvHook(msg); ok {
+					return msg, nil
+				} // else loop
+				msg.Free()
+			} else {
+				return msg, nil
+			}
+		case <-sock.closeq:
+			return nil, ErrClosed
+		case <-sock.recverrq:
+		}
+	}
+}
+
+func (sock *socket) Recv() ([]byte, error) {
+	msg, err := sock.RecvMsg()
+	if err != nil {
+		return nil, err
+	}
+	b := make([]byte, 0, len(msg.Body))
+	b = append(b, msg.Body...)
+	msg.Free()
+	return b, nil
+}
+
+func (sock *socket) getTransport(addr string) Transport {
+	var i int
+
+	if i = strings.Index(addr, "://"); i < 0 {
+		return nil
+	}
+	scheme := addr[:i]
+
+	sock.Lock()
+	defer sock.Unlock()
+
+	t, ok := sock.transports[scheme]
+	if t != nil && ok {
+		return t
+	}
+	return nil
+}
+
+func (sock *socket) AddTransport(t Transport) {
+	sock.Lock()
+	sock.transports[t.Scheme()] = t
+	sock.Unlock()
+}
+
+func (sock *socket) DialOptions(addr string, opts map[string]interface{}) error {
+
+	d, err := sock.NewDialer(addr, opts)
+	if err != nil {
+		return err
+	}
+	return d.Dial()
+}
+
+func (sock *socket) Dial(addr string) error {
+	return sock.DialOptions(addr, nil)
+}
+
+func (sock *socket) NewDialer(addr string, options map[string]interface{}) (Dialer, error) {
+	var err error
+	d := &dialer{sock: sock, addr: addr, closeq: make(chan struct{})}
+	t := sock.getTransport(addr)
+	if t == nil {
+		return nil, ErrBadTran
+	}
+	if d.d, err = t.NewDialer(addr, sock); err != nil {
+		return nil, err
+	}
+	for n, v := range options {
+		if err = d.d.SetOption(n, v); err != nil {
+			return nil, err
+		}
+	}
+	return d, nil
+}
+
+func (sock *socket) ListenOptions(addr string, options map[string]interface{}) error {
+	l, err := sock.NewListener(addr, options)
+	if err != nil {
+		return err
+	}
+	if err = l.Listen(); err != nil {
+		return err
+	}
+	return nil
+}
+
+func (sock *socket) Listen(addr string) error {
+	return sock.ListenOptions(addr, nil)
+}
+
+func (sock *socket) NewListener(addr string, options map[string]interface{}) (Listener, error) {
+	// This function sets up a goroutine to accept inbound connections.
+	// The accepted connection will be added to a list of accepted
+	// connections.  The Listener just needs to listen continuously,
+	// as we assume that we want to continue to receive inbound
+	// connections without limit.
+	t := sock.getTransport(addr)
+	if t == nil {
+		return nil, ErrBadTran
+	}
+	var err error
+	l := &listener{sock: sock, addr: addr}
+	l.l, err = t.NewListener(addr, sock)
+	if err != nil {
+		return nil, err
+	}
+	for n, v := range options {
+		if err = l.l.SetOption(n, v); err != nil {
+			l.l.Close()
+			return nil, err
+		}
+	}
+	return l, nil
+}
+
+func (sock *socket) SetOption(name string, value interface{}) error {
+	matched := false
+	err := sock.proto.SetOption(name, value)
+	if err == nil {
+		matched = true
+	} else if err != ErrBadOption {
+		return err
+	}
+	switch name {
+	case OptionRecvDeadline:
+		sock.Lock()
+		sock.rdeadline = value.(time.Duration)
+		sock.Unlock()
+		return nil
+	case OptionSendDeadline:
+		sock.Lock()
+		sock.wdeadline = value.(time.Duration)
+		sock.Unlock()
+		return nil
+	case OptionLinger:
+		sock.Lock()
+		sock.linger = value.(time.Duration)
+		sock.Unlock()
+		return nil
+	case OptionWriteQLen:
+		sock.Lock()
+		defer sock.Unlock()
+		if sock.active {
+			return ErrBadOption
+		}
+		length := value.(int)
+		if length < 0 {
+			return ErrBadValue
+		}
+		owq := sock.uwq
+		sock.uwqLen = length
+		sock.uwq = make(chan *Message, sock.uwqLen)
+		close(owq)
+		return nil
+	case OptionReadQLen:
+		sock.Lock()
+		defer sock.Unlock()
+		if sock.active {
+			return ErrBadOption
+		}
+		length := value.(int)
+		if length < 0 {
+			return ErrBadValue
+		}
+		sock.urqLen = length
+		sock.urq = make(chan *Message, sock.urqLen)
+		return nil
+	case OptionMaxRecvSize:
+		sock.Lock()
+		defer sock.Unlock()
+		switch value := value.(type) {
+		case int:
+			if value < 0 {
+				return ErrBadValue
+			}
+			sock.maxRxSize = value
+			return nil
+		default:
+			return ErrBadValue
+		}
+	case OptionReconnectTime:
+		sock.Lock()
+		sock.reconntime = value.(time.Duration)
+		sock.Unlock()
+		return nil
+	case OptionMaxReconnectTime:
+		sock.Lock()
+		sock.reconnmax = value.(time.Duration)
+		sock.Unlock()
+		return nil
+	case OptionBestEffort:
+		sock.Lock()
+		sock.bestEffort = value.(bool)
+		sock.Unlock()
+		return nil
+	}
+	if matched {
+		return nil
+	}
+	return ErrBadOption
+}
+
+func (sock *socket) GetOption(name string) (interface{}, error) {
+	val, err := sock.proto.GetOption(name)
+	if err == nil {
+		return val, nil
+	}
+	if err != ErrBadOption {
+		return nil, err
+	}
+
+	switch name {
+	case OptionRecvDeadline:
+		sock.Lock()
+		defer sock.Unlock()
+		return sock.rdeadline, nil
+	case OptionSendDeadline:
+		sock.Lock()
+		defer sock.Unlock()
+		return sock.wdeadline, nil
+	case OptionLinger:
+		sock.Lock()
+		defer sock.Unlock()
+		return sock.linger, nil
+	case OptionWriteQLen:
+		sock.Lock()
+		defer sock.Unlock()
+		return sock.uwqLen, nil
+	case OptionReadQLen:
+		sock.Lock()
+		defer sock.Unlock()
+		return sock.urqLen, nil
+	case OptionMaxRecvSize:
+		sock.Lock()
+		defer sock.Unlock()
+		return sock.maxRxSize, nil
+	case OptionReconnectTime:
+		sock.Lock()
+		defer sock.Unlock()
+		return sock.reconntime, nil
+	case OptionMaxReconnectTime:
+		sock.Lock()
+		defer sock.Unlock()
+		return sock.reconnmax, nil
+	}
+	return nil, ErrBadOption
+}
+
+func (sock *socket) GetProtocol() Protocol {
+	return sock.proto
+}
+
+func (sock *socket) SetPortHook(newhook PortHook) PortHook {
+	sock.Lock()
+	oldhook := sock.porthook
+	sock.porthook = newhook
+	sock.Unlock()
+	return oldhook
+}
+
+type dialer struct {
+	d      PipeDialer
+	sock   *socket
+	addr   string
+	closed bool
+	active bool
+	closeq chan struct{}
+}
+
+func (d *dialer) Dial() error {
+	d.sock.Lock()
+	if d.active {
+		d.sock.Unlock()
+		return ErrAddrInUse
+	}
+	d.closeq = make(chan struct{})
+	d.sock.active = true
+	d.active = true
+	d.sock.Unlock()
+	go d.dialer()
+	return nil
+}
+
+func (d *dialer) Close() error {
+	d.sock.Lock()
+	if d.closed {
+		d.sock.Unlock()
+		return ErrClosed
+	}
+	d.closed = true
+	close(d.closeq)
+	d.sock.Unlock()
+	return nil
+}
+
+func (d *dialer) GetOption(n string) (interface{}, error) {
+	return d.d.GetOption(n)
+}
+
+func (d *dialer) SetOption(n string, v interface{}) error {
+	return d.d.SetOption(n, v)
+}
+
+func (d *dialer) Address() string {
+	return d.addr
+}
+
+// dialer is used to dial or redial from a goroutine.
+func (d *dialer) dialer() {
+	rtime := d.sock.reconntime
+	rtmax := d.sock.reconnmax
+	for {
+		p, err := d.d.Dial()
+		if err == nil {
+			// reset retry time
+			rtime = d.sock.reconntime
+			d.sock.Lock()
+			if d.closed {
+				d.sock.Unlock()
+				p.Close()
+				return
+			}
+			d.sock.Unlock()
+			if cp := d.sock.addPipe(p, d, nil); cp != nil {
+				select {
+				case <-d.sock.closeq: // parent socket closed
+				case <-cp.closeq: // disconnect event
+				case <-d.closeq: // dialer closed
+				}
+			}
+		}
+
+		// we're redialing here
+		select {
+		case <-d.closeq: // dialer closed
+			if p != nil {
+				p.Close()
+			}
+			return
+		case <-d.sock.closeq: // exit if parent socket closed
+			if p != nil {
+				p.Close()
+			}
+			return
+		case <-time.After(rtime):
+			if rtmax > 0 {
+				rtime *= 2
+				if rtime > rtmax {
+					rtime = rtmax
+				}
+			}
+			continue
+		}
+	}
+}
+
+type listener struct {
+	l    PipeListener
+	sock *socket
+	addr string
+}
+
+func (l *listener) GetOption(n string) (interface{}, error) {
+	return l.l.GetOption(n)
+}
+
+func (l *listener) SetOption(n string, v interface{}) error {
+	return l.l.SetOption(n, v)
+}
+
+// serve spins in a loop, calling the accepter's Accept routine.
+func (l *listener) serve() {
+	for {
+		select {
+		case <-l.sock.closeq:
+			return
+		default:
+		}
+
+		// If the underlying PipeListener is closed, or not
+		// listening, we expect to return back with an error.
+		if pipe, err := l.l.Accept(); err == nil {
+			l.sock.addPipe(pipe, nil, l)
+		} else if err == ErrClosed {
+			return
+		}
+	}
+}
+
+func (l *listener) Listen() error {
+	// This function sets up a goroutine to accept inbound connections.
+	// The accepted connection will be added to a list of accepted
+	// connections.  The Listener just needs to listen continuously,
+	// as we assume that we want to continue to receive inbound
+	// connections without limit.
+
+	if err := l.l.Listen(); err != nil {
+		return err
+	}
+	l.sock.Lock()
+	l.sock.listeners = append(l.sock.listeners, l)
+	l.sock.active = true
+	l.sock.Unlock()
+	go l.serve()
+	return nil
+}
+
+func (l *listener) Address() string {
+	return l.l.Address()
+}
+
+func (l *listener) Close() error {
+	return l.l.Close()
+}

