+// Package tcp implements the TCP transport for mangos.
+package tcp
+
+import (
+	"net"
+	"time"
+
+	"nanomsg.org/go-mangos"
+)
+
+// options is used for shared GetOption/SetOption logic.
+type options map[string]interface{}
+
+// GetOption retrieves an option value.
+func (o options) get(name string) (interface{}, error) {
+	v, ok := o[name]
+	if !ok {
+		return nil, mangos.ErrBadOption
+	}
+	return v, nil
+}
+
+// SetOption sets an option.
+func (o options) set(name string, val interface{}) error {
+	switch name {
+	case mangos.OptionNoDelay:
+		fallthrough
+	case mangos.OptionKeepAlive:
+		switch v := val.(type) {
+		case bool:
+			o[name] = v
+			return nil
+		default:
+			return mangos.ErrBadValue
+		}
+	case mangos.OptionKeepAliveTime:
+		switch v := val.(type) {
+		case time.Duration:
+			if v.Nanoseconds() >= 0 {
+				o[name] = v
+				return nil
+			} else {
+				return mangos.ErrBadValue
+			}
+		default:
+			return mangos.ErrBadValue
+		}
+	}
+	return mangos.ErrBadOption
+}
+
+func newOptions() options {
+	o := make(map[string]interface{})
+	o[mangos.OptionNoDelay] = true
+	o[mangos.OptionKeepAlive] = true
+	return options(o)
+}
+
+func (o options) configTCP(conn *net.TCPConn) error {
+	if v, ok := o[mangos.OptionNoDelay]; ok {
+		if err := conn.SetNoDelay(v.(bool)); err != nil {
+			return err
+		}
+	}
+	if v, ok := o[mangos.OptionKeepAlive]; ok {
+		if err := conn.SetKeepAlive(v.(bool)); err != nil {
+			return err
+		}
+	}
+	if v, ok := o[mangos.OptionKeepAliveTime]; ok {
+		if err := conn.SetKeepAlivePeriod(v.(time.Duration)); err != nil {
+			return err
+		}
+	}
+	return nil
+}
+
+type dialer struct {
+	addr string
+	sock mangos.Socket
+	opts options
+}
+
+func (d *dialer) Dial() (_ mangos.Pipe, err error) {
+	var (
+		addr *net.TCPAddr
+	)
+
+	if addr, err = mangos.ResolveTCPAddr(d.addr); err != nil {
+		return nil, err
+	}
+
+	conn, err := net.DialTCP("tcp", nil, addr)
+	if err != nil {
+		return nil, err
+	}
+	if err = d.opts.configTCP(conn); err != nil {
+		conn.Close()
+		return nil, err
+	}
+
+	return mangos.NewConnPipe(conn, d.sock)
+}
+
+func (d *dialer) SetOption(n string, v interface{}) error {
+	return d.opts.set(n, v)
+}
+
+func (d *dialer) GetOption(n string) (interface{}, error) {
+	return d.opts.get(n)
+}
+
+type listener struct {
+	addr     *net.TCPAddr
+	bound    net.Addr
+	sock     mangos.Socket
+	listener *net.TCPListener
+	opts     options
+}
+
+func (l *listener) Accept() (mangos.Pipe, error) {
+
+	if l.listener == nil {
+		return nil, mangos.ErrClosed
+	}
+	conn, err := l.listener.AcceptTCP()
+	if err != nil {
+		return nil, err
+	}
+	if err = l.opts.configTCP(conn); err != nil {
+		conn.Close()
+		return nil, err
+	}
+	return mangos.NewConnPipe(conn, l.sock)
+}
+
+func (l *listener) Listen() (err error) {
+	l.listener, err = net.ListenTCP("tcp", l.addr)
+	if err == nil {
+		l.bound = l.listener.Addr()
+	}
+	return
+}
+
+func (l *listener) Address() string {
+	if b := l.bound; b != nil {
+		return "tcp://" + b.String()
+	}
+	return "tcp://" + l.addr.String()
+}
+
+func (l *listener) Close() error {
+	l.listener.Close()
+	return nil
+}
+
+func (l *listener) SetOption(n string, v interface{}) error {
+	return l.opts.set(n, v)
+}
+
+func (l *listener) GetOption(n string) (interface{}, error) {
+	return l.opts.get(n)
+}
+
+type tcpTran struct {
+	localAddr net.Addr
+}
+
+func (t *tcpTran) Scheme() string {
+	return "tcp"
+}
+
+func (t *tcpTran) NewDialer(addr string, sock mangos.Socket) (mangos.PipeDialer, error) {
+	var err error
+	if addr, err = mangos.StripScheme(t, addr); err != nil {
+		return nil, err
+	}
+
+	// check to ensure the provided addr resolves correctly.
+	if _, err = mangos.ResolveTCPAddr(addr); err != nil {
+		return nil, err
+	}
+
+	d := &dialer{addr: addr, sock: sock, opts: newOptions()}
+
+	return d, nil
+}
+
+func (t *tcpTran) NewListener(addr string, sock mangos.Socket) (mangos.PipeListener, error) {
+	var err error
+	l := &listener{sock: sock, opts: newOptions()}
+
+	if addr, err = mangos.StripScheme(t, addr); err != nil {
+		return nil, err
+	}
+
+	if l.addr, err = mangos.ResolveTCPAddr(addr); err != nil {
+		return nil, err
+	}
+
+	return l, nil
+}
+
+// NewTransport allocates a new TCP transport.
+func NewTransport() mangos.Transport {
+	return &tcpTran{}
+}

